function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // turtle
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 - 20, H/2 + 60);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20, H/2 + 60);
  ctx.stroke();

  // finish line
  ctx.beginPath();
  ctx.moveTo(W - 20, 0);
  ctx.lineTo(W - 20, H);
  ctx.stroke();

  // other racers
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t) * 100, H/2 + Math.sin(t * 2) * 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t * 2) * 150, H/2 + Math.sin(t) * 100, 20, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
